"""CRUD endpoints for posts."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Post
from app.schemas import PostCreate, PostRead, PostUpdate

router = APIRouter(prefix="/posts", tags=["posts"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, post_id: int) -> Post:
    post = session.get(Post, post_id)
    if post is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Post not found")
    return post


@router.get("", response_model=list[PostRead])
def list_posts(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Post]:
    query = select(Post).order_by(Post.id).offset(offset).limit(limit)
    return list(session.scalars(query))


@router.post("", response_model=PostRead, status_code=status.HTTP_201_CREATED)
def create_post(payload: PostCreate, session: SessionDep) -> Post:
    post = Post(**payload.model_dump())
    session.add(post)
    session.commit()
    session.refresh(post)
    return post


@router.get("/{post_id}", response_model=PostRead)
def get_post(post_id: int, session: SessionDep) -> Post:
    return _get_or_404(session, post_id)


@router.patch("/{post_id}", response_model=PostRead)
def update_post(
    post_id: int,
    payload: PostUpdate,
    session: SessionDep,
) -> Post:
    post = _get_or_404(session, post_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(post, key, value)
    session.commit()
    session.refresh(post)
    return post


@router.delete("/{post_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_post(post_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, post_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

